fn csv_to_vec(csv: Str) -> Vec[Str] {
  return str_split(csv, ",");
}

fn vec_to_csv(items: Vec[Str]) -> Str {
  return join(items, ",");
}

fn parse_tags(tag_str: Str) -> Int {
  let tags = str_split(tag_str, ",");
  return tags.len();
}

fn main() -> Int {
  return parse_tags("rust,systems,language");
}
